import { jsPDF } from 'jspdf';
import { CONFIG } from '../data/config';

interface PdfResult {
    type: string;
    model: string;
    flow: string;
    vol: string;
    apts: number;
    specs?: {
        resin?: string;
        hardness?: string;
        flow1b?: string;
        dims?: string;
        pressure?: string;
        temp?: string;
        link?: string;
    } | null;
}

interface ReportPage2Data {
    reportID: string;
    reportDate: string;
    projectName: string;
    locationName: string;
    hardnessF: number;
    dailyVolumeM3: number;
    apartmentCount: number;
    occupantCount: number;
    model: string;
    resinDescription: string;
    columnCount: number;
}

const DEEP_SEA = [0, 46, 77] as const;
const BLUE = [0, 53, 148] as const;
const CYAN = [41, 143, 194] as const;
const LIGHT_STEEL = [233, 234, 234] as const;
const AQUA_LOGO_DATA_URL = 'data:image/png;base64,';
const WQA_LOGO_DATA_URL = 'data:image/png;base64,';

function addReportHeader(doc: jsPDF, reportID: string, reportDate: string): void {
    doc.addImage(AQUA_LOGO_DATA_URL, 'PNG', 20, 9, 52, 15, undefined, 'FAST');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.setTextColor(...DEEP_SEA);
    doc.text(`Rapport N° ${reportID}`, 190, 14, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(95);
    doc.text(`Date : ${reportDate}`, 190, 20, { align: 'right' });
    doc.text(`${CONFIG.contact.address}  |  ${CONFIG.contact.phone}  |  ${CONFIG.contact.web}`, 20, 31);
    doc.setDrawColor(...CYAN);
    doc.setLineWidth(0.7);
    doc.line(20, 35, 190, 35);
}

function addReportFooter(doc: jsPDF, pageNumber: string, disclaimer: string): void {
    doc.setDrawColor(...LIGHT_STEEL);
    doc.setLineWidth(0.3);
    doc.line(20, 276, 190, 276);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(120);
    doc.text(disclaimer, 20, 282);
    doc.setFontSize(8);
    doc.setTextColor(...DEEP_SEA);
    doc.text(pageNumber, 190, 288, { align: 'right' });
}

function formatDecimal(value: number, digits = 2): string {
    return value.toFixed(digits).replace('.', ',');
}

function addWrappedText(
    doc: jsPDF,
    text: string,
    x: number,
    y: number,
    width: number,
    lineHeight = 4.1
): number {
    const lines = doc.splitTextToSize(text, width) as string[];
    doc.text(lines, x, y);
    return y + lines.length * lineHeight;
}

function addSectionTitle(doc: jsPDF, title: string, y: number): number {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...BLUE);
    doc.text(title, 20, y);
    doc.setDrawColor(...BLUE);
    doc.setLineWidth(0.35);
    doc.line(20, y + 2, 190, y + 2);
    return y + 7;
}

function addBullet(
    doc: jsPDF,
    label: string,
    text: string,
    x: number,
    y: number,
    width: number
): number {
    doc.setFillColor(...CYAN);
    doc.circle(x + 1, y - 1, 0.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.text(label, x + 4, y);
    doc.setFont('helvetica', 'normal');
    const body = text.replace(/^\s*:\s*/, '');
    const lines = doc.splitTextToSize(body, width - 8) as string[];
    doc.text(lines, x + 4, y + 3.8);
    return y + 3.8 + Math.max(1, lines.length) * 3.6 + 1.8;
}

function formatInteger(value: number): string {
    return Math.round(value).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

function formatEuro(value: number): string {
    return `${formatInteger(value)} €`;
}

function addFinancialCard(
    doc: jsPDF,
    title: string,
    items: Array<{ label: string; amount: string; text: string }>,
    x: number,
    y: number,
    width: number,
    height: number
): void {
    doc.setFillColor(248, 249, 250);
    doc.setDrawColor(234, 234, 234);
    doc.setLineWidth(0.3);
    doc.roundedRect(x, y, width, height, 2, 2, 'FD');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(...BLUE);
    doc.text(title, x + 5, y + 7);

    let itemY = y + 14;
    items.forEach(item => {
        doc.setFillColor(...CYAN);
        doc.circle(x + 5, itemY - 1, 0.7, 'F');
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(8);
        doc.setTextColor(55);
        doc.text(item.label, x + 8, itemY);
        doc.setTextColor(...CYAN);
        doc.text(item.amount, x + 8, itemY + 4);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(68);
        doc.setFontSize(7.6);
        const lines = doc.splitTextToSize(item.text, width - 13) as string[];
        doc.text(lines, x + 8, itemY + 8);
        itemY += 8 + lines.length * 3.2 + 2.4;
    });
}

function addReportPage2(doc: jsPDF, data: ReportPage2Data): void {
    const annualVolumeM3 = data.dailyVolumeM3 * 365;
    // 1 °f correspond à 10 mg/L de CaCO3, soit 10 g/m3.
    const limestoneKg = Math.round((annualVolumeM3 * data.hardnessF * 10) / 1000);

    const savings = {
        energy: { min: 30 * data.occupantCount, max: 70 * data.occupantCount },
        plumbing: { min: 120 * data.occupantCount, max: 250 * data.occupantCount },
        maintenance: { min: 55 * data.occupantCount, max: 115 * data.occupantCount },
        detergents: { min: 75 * data.occupantCount, max: 155 * data.occupantCount }
    };
    const totalMin = Object.values(savings).reduce((sum, item) => sum + item.min, 0);
    const totalMax = Object.values(savings).reduce((sum, item) => sum + item.max, 0);

    doc.addPage();
    addReportHeader(doc, data.reportID, data.reportDate);

    doc.setFontSize(9);
    doc.setTextColor(45);
    let y = addSectionTitle(doc, '1. Retrait du calcaire : mesurable et garanti', 45);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(45);
    y = addWrappedText(
        doc,
        'Contrairement aux dispositifs "anticalcaires" magnétiques ou galvaniques, qui maintiennent le calcaire en suspension sans l’éliminer ni garantir le résultat, l’adoucisseur à échange ionique retire physiquement les minéraux incrustants. Son efficacité se vérifie par une simple analyse de l’eau.',
        20,
        y,
        170,
        4.2
    );

    doc.setFillColor(244, 247, 251);
    doc.rect(20, y + 2, 170, 25, 'F');
    doc.setDrawColor(...BLUE);
    doc.setLineWidth(1.4);
    doc.line(20, y + 2, 20, y + 27);
    doc.setFontSize(9.2);
    doc.setTextColor(...BLUE);
    doc.setFont('helvetica', 'bold');
    doc.text(`Bilan pour ${data.projectName} :`, 25, y + 8);
    doc.setTextColor(35);
    doc.setFont('helvetica', 'normal');
    const projectSummary = `Selon les données gouvernementales publiées sur data.public.lu, la dureté de l’eau à ${data.locationName} est de ${formatDecimal(data.hardnessF, 1)} °f. Pour une consommation estimée à ${formatDecimal(data.dailyVolumeM3)} m³/jour et ${data.occupantCount} résidents, le système interceptera et évacuera environ ${formatInteger(limestoneKg)} kg de calcaire par an (exprimé en CaCO3).`;
    addWrappedText(doc, projectSummary, 25, y + 14, 160, 4);
    y += 33;

    y = addSectionTitle(doc, '2. Bilan financier : protection et économies estimées', y);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(45);
    doc.setFontSize(9);
    y = addWrappedText(
        doc,
        `En protégeant ${data.apartmentCount} appartements, l’installation générera une économie globale estimée entre ${formatEuro(totalMin)} et ${formatEuro(totalMax)} par an pour l’ensemble du bâtiment, répartie entre charges communes et dépenses privatives.`,
        20,
        y,
        170,
        4.1
    ) + 2;

    addFinancialCard(doc, 'Pour la copropriété', [
        {
            label: 'Plomberie & appareils',
            amount: `${formatEuro(savings.plumbing.min)} - ${formatEuro(savings.plumbing.max)}`,
            text: 'Arrêt de l’entartrage, baisse des interventions d’urgence et durée de vie accrue des équipements communs.'
        },
        {
            label: 'Énergie',
            amount: `${formatEuro(savings.energy.min)} - ${formatEuro(savings.energy.max)}`,
            text: 'Maintien du rendement des échangeurs thermiques, le tartre agissant comme un isolant.'
        }
    ], 20, y, 81, 48);
    addFinancialCard(doc, 'Pour les résidents', [
        {
            label: 'Savon & lessive',
            amount: `${formatEuro(savings.detergents.min)} - ${formatEuro(savings.detergents.max)}`,
            text: 'Pouvoir moussant accru et réduction possible de moitié des dosages de détergents.'
        },
        {
            label: 'Entretien',
            amount: `${formatEuro(savings.maintenance.min)} - ${formatEuro(savings.maintenance.max)}`,
            text: 'Suppression de la corvée de détartrage et réduction des produits chimiques anticalcaires.'
        }
    ], 109, y, 81, 48);
    y += 54;

    doc.setFontSize(9);
    y = addSectionTitle(doc, `3. Pourquoi le ${data.model} ?`, y);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(45);
    doc.setFontSize(8.5);
    y = addWrappedText(doc, `Pour garantir une continuité de service irréprochable et maîtriser les charges communes de ${data.projectName}, ce modèle surpasse les standards du marché :`, 20, y, 170, 3.8) + 2;
    y = addBullet(doc, 'Conception duplex (eau douce 24 h/24)', ` : équipé de ${data.columnCount} colonnes de résine (${data.resinDescription}), le système assure la relève pendant la régénération, sans interruption de service 24/7.`, 20, y, 170);
    y = addBullet(doc, 'Régénération à l’eau traitée', ' : l’appareil utilise de l’eau adoucie pour nettoyer ses résines et préserver leur efficacité.', 20, y, 170);
    y = addBullet(doc, 'Consommation ajustée au strict minimum', ` : le fonctionnement volumétrique s’adapte à la présence réelle des ${data.occupantCount} résidents et ne régénère qu’en fonction des besoins.`, 20, y, 170);
    y = addBullet(doc, 'Fiabilité 100 % autonome', ' : fonctionnement hydraulique sans électricité, sans carte électronique et sans programmation. Certifications NSF et WQA.', 20, y, 170);

    doc.setFontSize(9);
    y = addSectionTitle(doc, '4. L’expertise Aqua Purify', y + 1);
    doc.setFontSize(8.5);
    doc.setTextColor(45);
    doc.addImage(WQA_LOGO_DATA_URL, 'PNG', 20, y - 2, 26, 24, undefined, 'FAST');
    doc.setFontSize(8.2);
    doc.setTextColor(55);
    doc.setFont('helvetica', 'bold');
    doc.text('Certification internationale', 54, y + 1);
    doc.setFont('helvetica', 'normal');
    y = addWrappedText(doc, 'Certified Water Specialist par la WQA.', 54, y + 5, 136, 3.7);
    doc.setFont('helvetica', 'bold');
    doc.text('Entreprise locale', 54, y + 1);
    doc.setFont('helvetica', 'normal');
    addWrappedText(doc, 'Une présence de proximité assurant réactivité, entretien, et suivi technique de l’installation.', 54, y + 5, 136, 3.7);

    addReportFooter(doc, '2/2', 'Estimations issues des données saisies. Validation technique sur site requise avant toute offre définitive.');
}

export function generatePDF(projectRef: string, communeName: string, currentTH: number, currentResult: PdfResult): void {
    const doc = new jsPDF();
    const now = new Date();
    const dateStr = now.toLocaleDateString('fr-FR');
    const reportID = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${Math.floor(Math.random() * 90 + 10)}`;
    const projName = projectRef || 'Non spécifié';

    addReportHeader(doc, reportID, dateStr);

    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...DEEP_SEA);
    doc.text('1. Identification du projet', 20, 47);
    doc.setFontSize(11);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(0);
    doc.text(`Référence : ${projName}`, 25, 55);
    doc.text(`Localisation : ${communeName}`, 25, 62);
    doc.text(`Dureté (TH) : ${formatDecimal(currentTH, 1)} °f  /  ${formatDecimal(currentTH * 0.56, 1)} °dH`, 25, 69);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...DEEP_SEA);
    doc.text('2. Données techniques de dimensionnement', 20, 82);

    let currentY = 91;
    doc.setFontSize(9.2);

    if (currentResult.type === 'collectif') {
        const apartmentCount = Math.max(1, Number(currentResult.apts) || 1);
        const sumDesignFlowLS = apartmentCount * CONFIG.constants.vrPerApt;
        const peakFlowLS = CONFIG.constants.coefA * Math.pow(sumDesignFlowLS, CONFIG.constants.coefB) - CONFIG.constants.coefC;
        const peakFlowM3H = peakFlowLS * 3.6;
        const occupantCount = apartmentCount * CONFIG.constants.personsPerApt;
        const dailyVolumeL = occupantCount * CONFIG.constants.consumptionPerPerson;

        doc.setFillColor(246, 249, 251);
        doc.setDrawColor(...LIGHT_STEEL);
        doc.roundedRect(20, 87, 170, 50, 2, 2, 'FD');
        doc.setTextColor(45);
        doc.setFont('helvetica', 'normal');
        doc.text(`Bâtiment résidentiel collectif : ${apartmentCount} appartements / ${occupantCount} résidents estimés`, 25, currentY);
        currentY += 7;
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...BLUE);
        doc.text('Base de calcul : DIN 1988-300', 25, currentY);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(45);
        currentY += 7;
        doc.text(`Somme des débits de calcul : ${apartmentCount} x ${formatDecimal(CONFIG.constants.vrPerApt)} = ${formatDecimal(sumDesignFlowLS)} L/s`, 25, currentY);
        currentY += 7;
        doc.text(`Débit de pointe : Vs = ${formatDecimal(CONFIG.constants.coefA)} x (${formatDecimal(sumDesignFlowLS)})^${formatDecimal(CONFIG.constants.coefB)} - ${formatDecimal(CONFIG.constants.coefC)} = ${formatDecimal(peakFlowLS)} L/s`, 25, currentY);
        currentY += 7;
        doc.text(`Soit ${formatDecimal(peakFlowM3H)} m³/h. Volume journalier : ${occupantCount} x ${CONFIG.constants.consumptionPerPerson} L = ${formatInteger(dailyVolumeL)} L (${formatDecimal(dailyVolumeL / 1000)} m³/jour).`, 25, currentY);
        currentY = 143;
    } else {
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(45);
        doc.text(`Type de bâtiment : ${currentResult.type === 'maison' ? 'Maison unifamiliale' : 'Appartement'}`, 25, currentY);
        currentY = 108;
    }

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...DEEP_SEA);
    doc.text('3. Préconisation / application', 20, currentY);

    const boxY = currentY + 6;
    doc.setFillColor(245, 245, 245);
    doc.rect(20, boxY, 170, 55, 'F');
    doc.setFillColor(...CYAN);
    doc.rect(20, boxY, 2, 55, 'F');

    doc.setFontSize(16);
    doc.setTextColor(...BLUE);
    doc.setFont('helvetica', 'bold');
    doc.text(currentResult.model, 105, boxY + 12, { align: 'center' });

    if (currentResult.specs) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(10);
        doc.setTextColor(50);
        let specY = boxY + 25;
        doc.text(`Résine : ${currentResult.specs.resin ?? '-'}`, 30, specY);
        doc.text(`Dureté max. : ${currentResult.specs.hardness ?? '-'}`, 110, specY);
        specY += 8;
        doc.text(`Débit pointe (1 bar) : ${currentResult.specs.flow1b ?? '-'}`, 30, specY);
        doc.text(`Dimensions : ${currentResult.specs.dims ?? '-'}`, 110, specY);
        specY += 8;
        doc.text(`Pression : ${currentResult.specs.pressure ?? '-'}`, 30, specY);
        doc.text(`Température : ${currentResult.specs.temp ?? '-'}`, 110, specY);

        if (currentResult.specs.link) {
            const linkLabel = 'Voir la fiche technique';
            const linkX = 79;
            const linkY = boxY + 45;
            const linkWidth = 52;
            const linkHeight = 7;
            doc.setFillColor(255, 255, 255);
            doc.setDrawColor(...BLUE);
            doc.setLineWidth(0.35);
            doc.roundedRect(linkX, linkY, linkWidth, linkHeight, 1.5, 1.5, 'FD');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8);
            doc.setTextColor(...BLUE);
            doc.text(linkLabel, 105, linkY + 4.7, { align: 'center' });
            doc.link(linkX, linkY, linkWidth, linkHeight, { url: currentResult.specs.link });
        }
    }

    addReportFooter(doc, currentResult.type === 'collectif' ? '1/2' : '1/1', 'Simulation technique indicative fournie par Aqua Purify. Validation sur site requise.');

    if (currentResult.type === 'collectif') {
        const apartmentCount = Math.max(1, Number(currentResult.apts) || 1);
        const resinDescription = currentResult.specs?.resin || 'volume à confirmer';
        const columnCount = Number(resinDescription.match(/(\d+)\s*x/i)?.[1]) || 2;
        addReportPage2(doc, {
            reportID,
            reportDate: dateStr,
            projectName: projName,
            locationName: communeName,
            hardnessF: Math.max(0, currentTH),
            dailyVolumeM3: Math.max(0, Number(currentResult.vol) || 0),
            apartmentCount,
            occupantCount: Math.round(apartmentCount * CONFIG.constants.personsPerApt),
            model: currentResult.model || 'Kinetico',
            resinDescription,
            columnCount
        });
    }

    doc.save(`Dimensionnement_${reportID}.pdf`);
}
